{
  "spells": [
    {
      "id": "spell_fire_13",
      "theory": "烬雨术将火属魔力注入树脂媒介，在四十米内选定区域上方形成灼热火屑，如雨落下，不分敌我。火屑接触可燃物即引燃，对披甲者造成灼伤，对无防护者威胁更大。施术者需保持手势稳定，火屑密度受魔力量控制，但范围与伤害上限固定。",
      "casting": "左手托树脂，右手剑指划出燃烧符文，念出短促音节，随后将树脂抛向空中。",
      "failure": "树脂未燃尽便落地，火屑稀疏且提前熄灭，只留下焦痕与烟雾，可能引燃施术者脚边杂草。",
      "counters": [
        "以水幕或沙土覆盖落点，隔绝火屑与可燃物接触。",
        "用强风法术吹散火屑云，使其偏离目标区域。",
        "提前浸湿地面与衣物，降低引燃概率。"
      ],
      "socialConsequences": "乡约见证下，若在河谷使用烬雨术烧毁他人庄稼或草场，施术者须按约赔偿，并可能被要求为村落防火巡逻。城市公会严控此术，无许可施放视为纵火重罪，目击者会向守卫报告。琥珀海岸港务规定，在港口区施放导致货损或航运事故，船主与码头工可联合索赔，施术者可能被禁止进入码头。",
      "law": {
        "river": "public",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "低熟练度时火屑分布不均，边缘区域可能无火屑落下。",
        "熟练度提升后，火屑覆盖更均匀，减少意外引燃周边。",
        "高熟练度可微调火屑密度，但总伤害不变。",
        "顶尖熟练度使火屑落地时间更一致，便于控制火势。"
      ]
    },
    {
      "id": "spell_fire_14",
      "theory": "封焰结界以火属魔力在房屋边界形成半透膜，阻隔火焰与氧气交换，从而限制火势蔓延。结界需持续消耗魔力维持，内部火焰因缺氧逐渐减弱，但可能闷烧产生浓烟。结界不灭火，只隔绝，施术者离开或魔力耗尽则失效。",
      "casting": "沿房屋外墙行走，以树脂在墙角画出闭合符文，双手结印注入魔力，念出封禁咒文。",
      "failure": "符文未闭合，结界出现缺口，火焰从缺口窜出，浓烟泄漏，施术者可能吸入烟尘。",
      "counters": [
        "在结界外凿开通风口，平衡内外气压防止爆燃。",
        "用破魔法术击碎符文节点，解除结界。",
        "以水系法术从外部降温，辅助控制火势。"
      ],
      "socialConsequences": "河谷乡约鼓励村民学习此术，以便火灾时互助，但若因结界导致屋内人员窒息，施术者须承担过失责任。城市消防公会要求施术者登记，无证使用若造成损失按纵火论处。港口区货仓密集，港务规定施放封焰结界须经许可，以免影响其他货主，违规者面临罚款与禁入。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时结界薄膜薄弱，火焰可能从缝隙透出。",
        "熟练度提升后，结界维持时间更稳定，减少魔力浪费。",
        "高熟练度可精确控制结界范围，避免覆盖邻屋。",
        "顶尖熟练度使结界内缺氧过程更平缓，减少爆燃风险。"
      ]
    }
  ]
}
